// 3-DOF robot arm with analytic inverse kinematics.
// Send a target over Serial: "x y z g"  (mm and gripper 0..1), e.g. "120 40 60 0".
// Joints: base(yaw) + shoulder + elbow + wrist(kept level) + gripper. Servos need a
// SEPARATE 5-6V supply with COMMON GROUND. Calibrate OFFSET/DIR/limits for YOUR arm.
#include <Servo.h>
#include <math.h>

// --- arm geometry (mm) — measure your own ---
const float L1 = 105.0;      // shoulder -> elbow
const float L2 = 100.0;      // elbow -> wrist
const float BASE_H = 60.0;   // floor -> shoulder joint
const float GRIP_OFF = 45.0; // wrist -> gripper tip

// --- servos: pin, offsetDeg, dir(+1/-1), minUs, maxUs ---
Servo base, shoulder, elbow, wrist, grip;
const int PIN_BASE=3, PIN_SH=5, PIN_EL=6, PIN_WR=9, PIN_GR=10;

float qBase=0, qSh=PI/2, qEl=0, qWr=0;          // current angles (rad)
float tBase=0, tSh=PI/2, tEl=0, tWr=0; float tGrip=0;   // targets
const float SPEED = 1.5;                        // rad/s (smoothness)
unsigned long last=0;

int toUs(float rad, float offDeg, int dir, int minUs, int maxUs){
  float deg = degrees(rad)*dir + offDeg;
  deg = constrain(deg, 0, 180);
  return map((int)deg, 0, 180, minUs, maxUs);
}

// Solve IK for (x,y,z) in mm. Returns false if unreachable.
bool ik(float x, float y, float z){
  float b = atan2(y, x);
  float r = sqrt(x*x + y*y) - GRIP_OFF;         // horizontal reach to the wrist
  float zz = z - BASE_H;                        // height above shoulder
  float d2 = r*r + zz*zz;
  float reach = sqrt(d2);
  if (reach > L1 + L2 || reach < fabs(L1 - L2)) return false;   // out of range
  float cosE = (d2 - L1*L1 - L2*L2) / (2*L1*L2);
  cosE = constrain(cosE, -1.0, 1.0);
  float el = acos(cosE);                        // elbow-down
  float sh = atan2(zz, r) - atan2(L2*sin(el), L1 + L2*cos(el));
  tBase = b; tSh = sh; tEl = el;
  tWr = -(sh + el);                             // keep gripper roughly level
  return true;
}

void setup(){
  base.attach(PIN_BASE); shoulder.attach(PIN_SH); elbow.attach(PIN_EL);
  wrist.attach(PIN_WR); grip.attach(PIN_GR);
  Serial.begin(115200);
  Serial.println("IK arm ready. Send: x y z g   (mm, gripper 0..1). e.g. 120 40 60 0");
}

void loop(){
  // --- read a target line ---
  if (Serial.available()){
    String line = Serial.readStringUntil('\n');
    float x,y,z,g;
    if (sscanf(line.c_str(), "%f %f %f %f", &x,&y,&z,&g) >= 3){
      if (ik(x,y,z)){ tGrip = constrain(g,0,1); Serial.println("moving"); }
      else Serial.println("out of reach");
    }
  }
  // --- smooth motion toward targets ---
  if (millis() - last >= 20){
    float dt = (millis()-last)/1000.0; last = millis();
    float step = SPEED*dt;
    qBase += constrain(tBase-qBase, -step, step);
    qSh   += constrain(tSh  -qSh,   -step, step);
    qEl   += constrain(tEl  -qEl,   -step, step);
    qWr   += constrain(tWr  -qWr,   -step, step);
    base.writeMicroseconds(     toUs(qBase, 90, +1, 500, 2500));
    shoulder.writeMicroseconds( toUs(qSh,    0, +1, 500, 2500));
    elbow.writeMicroseconds(    toUs(qEl,    0, +1, 500, 2500));
    wrist.writeMicroseconds(    toUs(qWr,   90, +1, 500, 2500));
    grip.writeMicroseconds(     map((int)(tGrip*100), 0, 100, 1000, 2000));
  }
}
